import type { Context } from '@deepseek-ai/cordis';
import Schema from '@deepseek-ai/schemastery';
import { defineTool } from '@deepseek-ai/dsh-tools';
import type {} from '@deepseek-ai/dsh-commands';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync, existsSync, writeFileSync, renameSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join } from 'node:path';
import { quotaProjection, type QuotaState } from './projection.ts';

import {
  addUsage,
  calibratePrices,
  compactTokens,
  costMicrosOf,
  emptyTotals,
  predictNextTurn,
  presentCallCard,
  presentResultCard,
  priceFor,
  projectBudget,
  projectWindow,
  promptGrowth,
  renderBudgetLine,
  renderCompactLine,
  renderForecastLine,
  renderMeter,
  renderModelTop,
  renderWindowLine,
  stepOf,
  summarise,
  type PriceRow,
  type QuotaSummary,
  type RawUsage,
  type StepUsage,
  type UsageTotals,
} from './meter.ts';

export const name = 'quota';
export const inject = ['commands', 'tools', 'systemPrompt'];

export interface Config {
  enabled: boolean;
  dataPath?: string;
  budgetTokens: number;
  inject: boolean;
  prices: PriceRow[];
  billingDbPath?: string;
}

export const Config = Schema.object({
  enabled: Schema.boolean().default(true),
  dataPath: Schema.string(),
  budgetTokens: Schema.natural().default(0).description('单会话 token 预算，0 = 不显示进度条'),
  billingDbPath: Schema.string().description('new-api 的 one-api.db 路径；配置后自动从计费日志反推真实 $/M 价格，覆盖 prices'),
  inject: Schema.boolean().default(true).description('把实时仪表注入系统提示'),
  prices: Schema.array(
    Schema.object({
      match: Schema.string(),
      currency: Schema.string().default('CNY'),
      perMillion: Schema.object({
        input: Schema.number().default(0),
        output: Schema.number().default(0),
        cacheRead: Schema.number().default(0),
      }),
      contextWindow: Schema.number().description('该模型的上下文窗口，撑满预测的根据；缺省则不算撑满点'),
    }),
  ).default([]),
});

export function expandHome(path: string): string {
  return path.startsWith('~') ? join(homedir(), path.slice(1)) : path;
}

function writeAtomic(dest: string, content: string): void {
  mkdirSync(dirname(dest), { recursive: true });
  const tmp = `${dest}.${process.pid}.tmp`;
  writeFileSync(tmp, content, 'utf8');
  renameSync(tmp, dest);
}

/** Per-session step history backs the next-turn forecast. It lives in its own file
 * so `totals.json` stays the stable cross-plugin budget contract (task-forge reads it). */
const HISTORY_LIMIT = 64;

function isStep(value: unknown): value is StepUsage {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const step = value as Partial<StepUsage>;
  return [step.input, step.output, step.cacheRead].every((n) => typeof n === 'number' && Number.isFinite(n) && n >= 0);
}

export class MeterStore {
  readonly path: string;
  readonly historyPath: string;
  readonly summaryPath: string;
  constructor(dataPath: string | undefined) {
    this.path = dataPath ? expandHome(dataPath) : join(homedir(), '.dsh', 'quota', 'totals.json');
    this.historyPath = join(dirname(this.path), 'history.json');
    this.summaryPath = join(dirname(this.path), 'summary.json');
  }
  load(): Record<string, UsageTotals> {
    if (!existsSync(this.path)) return {};
    try {
      const parsed = JSON.parse(readFileSync(this.path, 'utf8'));
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? (parsed as Record<string, UsageTotals>) : {};
    } catch {
      return {};
    }
  }
  save(sessions: Record<string, UsageTotals>): void {
    writeAtomic(this.path, JSON.stringify(sessions, null, 2) + '\n');
  }
  loadHistory(): Record<string, StepUsage[]> {
    if (!existsSync(this.historyPath)) return {};
    try {
      const parsed = JSON.parse(readFileSync(this.historyPath, 'utf8'));
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
      const out: Record<string, StepUsage[]> = {};
      for (const [key, value] of Object.entries(parsed as Record<string, unknown>)) {
        if (Array.isArray(value)) out[key] = value.filter(isStep).slice(-HISTORY_LIMIT);
      }
      return out;
    } catch {
      return {};
    }
  }
  saveHistory(histories: Record<string, StepUsage[]>): void {
    writeAtomic(this.historyPath, JSON.stringify(histories, null, 2) + '\n');
  }
  saveSummary(summary: QuotaSummary): void {
    writeAtomic(this.summaryPath, JSON.stringify(summary, null, 2) + '\n');
  }
}

export function apply(ctx: Context, config: Config): void {
  const log = ctx.logger('quota');
  if (!config.enabled) return void log.info('disabled by config');
  if (!Number.isFinite(config.budgetTokens) || config.budgetTokens < 0) throw new TypeError('quota: budgetTokens must be a non-negative finite number');
  if (config.budgetTokens > 0 && !Number.isInteger(config.budgetTokens)) throw new TypeError('quota: budgetTokens must be an integer when set');
  for (const row of config.prices) {
    const contextWindow = row.contextWindow;
    if (contextWindow !== undefined && (!Number.isFinite(contextWindow) || contextWindow <= 0)) {
      throw new TypeError(`quota: prices[].contextWindow must be a positive finite number (match=${row.match})`);
    }
  }

  const store = new MeterStore(config.dataPath);
  /** tracked totals carry per-model buckets for /qm-top; files written before
   * byModel existed simply lack the key, so it stays optional on read. */
  type TrackedTotals = UsageTotals & { byModel?: Record<string, UsageTotals> };
  const sessions = new Map<string, TrackedTotals>(Object.entries(store.load()) as Array<[string, TrackedTotals]>);
  /** daily rollup keyed YYYY-MM-DD — session ids are uuids without dates, so
   * "today" cannot be derived by filtering session keys. In-memory only:
   * restarts zero it, a pre-existing behavior /qm-top's 今日 inherits. */
  const daily = new Map<string, TrackedTotals>();
  /** per-session step history + last-seen model: the basis for the next-turn forecast
   * and for both session projections (fill point, budget burn-out) */
  const histories = new Map<string, StepUsage[]>(Object.entries(store.loadHistory()));
  const lastModel = new Map<string, string>();
  let dirty = 0;

  let calibrated: PriceRow[] = [];
  if (config.billingDbPath) {
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const db = new DatabaseSync(expandHome(config.billingDbPath), { readOnly: true });
      const rows = db
        .prepare("SELECT model_name, quota, prompt_tokens + completion_tokens AS tokens FROM logs WHERE type = 2 ORDER BY created_at DESC LIMIT 500")
        .all() as Array<{ model_name: string; quota: number; tokens: number }>;
      db.close();
      calibrated = calibratePrices(rows.map((row) => ({ model: row.model_name, quota: Number(row.quota), tokens: Number(row.tokens) })));
      if (calibrated.length) log.info(`prices calibrated from billing logs: ${calibrated.length} models`);
    } catch (error) {
      log.warn(`price calibration skipped: ${String(error)}`);
    }
  }

  const options = (): { budgetTokens?: number; prices?: PriceRow[] } => ({
    ...(config.budgetTokens > 0 ? { budgetTokens: config.budgetTokens } : {}),
    ...(calibrated.length ? { prices: calibrated } : config.prices.length ? { prices: config.prices } : {}),
  });

  // Official projection model: the registry folds committed events eagerly and
  // replays the log on fork/resume, so per-session totals survive restarts —
  // the in-memory map below remains only for the daily rollup and as a
  // fallback when the projection seam is absent.
  try {
    (ctx as unknown as { inject?: (services: string[], setup: (sp: { register?: (definition: unknown) => unknown }) => void) => void }).inject?.(
      ['sessionProjections'],
      (sp) => {
        sp.register?.(quotaProjection(config.prices));
        log.info('quota projection registered');
      },
    );
  } catch (error) {
    log.warn(`projection registration skipped: ${String(error)}`);
  }

  const readProjectedState = (): QuotaState | null => {
    try {
      const session = (ctx as unknown as { agents?: { currentInitiator?: () => { session?: unknown } | undefined } | undefined }).agents?.currentInitiator?.()?.session;
      if (!session) return null;
      const sp = (ctx as unknown as { sessionProjections?: { stateOf?: (session: unknown, key: string) => QuotaState | undefined } | undefined }).sessionProjections;
      return sp?.stateOf?.(session, 'quota') ?? null;
    } catch {
      return null;
    }
  };

  const today = (): string => new Date().toISOString().slice(0, 10);

  /** Three folds stay per-model in lockstep — the projection (per-session state),
   * this in-memory fold (fallback + daily rollup) — so /qm-top reads the same
   * buckets no matter which path answered. */
  const fold = (map: Map<string, TrackedTotals>, key: string, usage: RawUsage, model: string): void => {
    let totals = map.get(key);
    if (!totals) {
      totals = { ...emptyTotals(), byModel: {} };
      map.set(key, totals);
    }
    const cost = costMicrosOf(priceFor(config.prices, model), usage);
    const folded = addUsage(totals, usage);
    folded.costMicros = totals.costMicros + cost;
    const buckets = { ...(totals.byModel ?? {}) };
    const bucket = addUsage(buckets[model] ?? emptyTotals(), usage);
    bucket.costMicros = bucket.costMicros + cost;
    buckets[model] = bucket;
    (folded as TrackedTotals).byModel = buckets;
    map.set(key, folded as TrackedTotals); // addUsage is pure — store the folded result back
  };

  ctx.on('session/event', (session, event) => {
    if (event.type !== 'assistant/message') return;
    const usage = (event.data as { usage?: RawUsage }).usage;
    if (!usage) return;
    const sessionId = String((session as { id?: unknown }).id ?? 'session');
    const model = (event.data as { message?: { source?: { model?: string } } }).message?.source?.model ?? 'unknown';
    fold(sessions, sessionId, usage, model);
    fold(daily, today(), usage, model);
    histories.set(sessionId, [...(histories.get(sessionId) ?? []), stepOf(usage)].slice(-HISTORY_LIMIT));
    lastModel.set(sessionId, model);
    if (++dirty % 4 === 0) {
      store.save(Object.fromEntries(sessions));
      store.saveHistory(Object.fromEntries(histories));
      publish();
    }
  });

  const forecastFor = (sessionId: string | undefined) =>
    predictNextTurn(sessionId === undefined ? [] : histories.get(sessionId) ?? [], sessionId === undefined ? null : priceFor(config.prices, lastModel.get(sessionId) ?? 'unknown'));

  const usedOf = (totals: UsageTotals | undefined): number => totals ? totals.inputTokens + totals.outputTokens : 0;

  /** dsh gives plugins no model catalogue, so the context window comes from config —
   * the same price row that matched the model, or no fill point at all. */
  const contextWindowOf = (sessionId: string | undefined): number | null =>
    sessionId === undefined ? null : priceFor(config.prices, lastModel.get(sessionId) ?? 'unknown')?.contextWindow ?? null;

  /** the two session projections: when the window fills, when the budget burns out */
  const projectFor = (sessionId: string | undefined) => {
    const history = sessionId === undefined ? [] : histories.get(sessionId) ?? [];
    const contextWindow = contextWindowOf(sessionId);
    const window = contextWindow === null ? null : projectWindow(history, contextWindow, sessionId === undefined ? 0 : sessions.get(sessionId)?.turns);
    const budget = projectBudget(usedOf(sessionId === undefined ? undefined : sessions.get(sessionId)), config.budgetTokens, promptGrowth(history));
    return { contextWindow, window, budget };
  };

  const projectionLines = (sessionId: string | undefined): string[] => {
    const { contextWindow, window, budget } = projectFor(sessionId);
    return [renderWindowLine(window, contextWindow), renderBudgetLine(budget)];
  };

  /** Republish the budget contract every time the meter is flushed — other plugins
   * read summary.json without knowing session ids. */
  const publish = (): void => {
    const id = currentSessionId();
    const { contextWindow, window, budget } = projectFor(id);
    const summary = summarise({
      sessions: [...sessions.values()],
      today: aggregateToday(),
      budgetTokens: config.budgetTokens,
      forecast: id === undefined ? null : forecastFor(id),
      currency: config.prices[0]?.currency,
      now: new Date(),
      contextWindow,
      stepsUntilFull: window?.stepsToFull ?? null,
      stepsUntilBudget: budget.stepsLeft,
    });
    store.saveSummary(summary);
  };

  const currentSessionId = (): string | undefined => {
    try {
      const initiator = (ctx as unknown as { agents?: { currentInitiator?: () => { session?: { id?: unknown } | undefined } | undefined } }).agents?.currentInitiator?.();
      const id = initiator?.session?.id;
      return id === undefined ? undefined : String(id);
    } catch {
      return undefined;
    }
  };

  const aggregateToday = (): UsageTotals => daily.get(today()) ?? emptyTotals();
  const aggregateAll = (): UsageTotals => {
    const all = emptyTotals();
    for (const totals of daily.values()) {
      all.inputTokens += totals.inputTokens;
      all.outputTokens += totals.outputTokens;
      all.cacheReadTokens += totals.cacheReadTokens;
      all.turns += totals.turns;
      all.costMicros += totals.costMicros;
    }
    return all;
  };

  if (config.inject) {
    ctx.systemPrompt.section({
      name: 'quota',
      order: 660,
      text: () => {
        try {
          const id = currentSessionId();
          const totals = readProjectedState() ?? (id !== undefined && sessions.has(id) ? sessions.get(id)! : aggregateToday());
          return totals.turns === 0 ? '' : renderCompactLine(totals, options());
        } catch (error) {
          log.warn(`quota section skipped: ${String(error)}`);
          return '';
        }
      },
    });
  }

  ctx.commands.register({
    name: 'qm',
    description: '实时用量仪表：本会话 token/步数/估算花费、下步预估与撑满/烧穿预测，及今日全部会话合计',
    handler: () => {
      const lines: string[] = [];
      const id = currentSessionId();
      const current = readProjectedState() ?? (id !== undefined ? sessions.get(id) : undefined);
      lines.push(renderMeter('▍ 本会话', current ?? emptyTotals(), options()));
      lines.push('');
      lines.push(renderForecastLine(current ? forecastFor(id) : null));
      lines.push(...projectionLines(id));
      lines.push('');
      lines.push(renderMeter('▍ 今日全部', aggregateToday(), options()));
      if (config.budgetTokens > 0 && current) {
        const used = usedOf(current);
        lines.push('');
        lines.push(used > config.budgetTokens ? `⚠ 已超出单会话预算 ${compactTokens(config.budgetTokens)}——收尾或 /qm-reset` : '');
      }
      return { kind: 'success', text: lines.filter((line) => line !== '').join('\n') };
    },
  });

  ctx.commands.register({
    name: 'qm-top',
    description: '按模型用量排行：本会话与今日全部会话的分模型 Top5（/qm-top）',
    handler: () => {
      try {
        const id = currentSessionId();
        const current = readProjectedState() ?? (id !== undefined ? sessions.get(id) : undefined);
        const todayTotals = daily.get(today());
        return {
          kind: 'success',
          text: [renderModelTop('▍ 本会话', current?.byModel, options()), '', renderModelTop('▍ 今日全部', todayTotals?.byModel, options())].join('\n'),
        };
      } catch (error) {
        return { kind: 'error', text: `/qm-top 内部出错：${String(error)}` };
      }
    },
  });

  ctx.commands.register({
    name: 'qm-reset',
    description: '清零实时用量仪表（全部会话），/qm 重新计',
    handler: () => {
      const count = sessions.size;
      sessions.clear();
      daily.clear();
      histories.clear();
      lastModel.clear();
      store.save({});
      store.saveHistory({});
      publish();
      return { kind: 'success', text: `已清零 ${count} 个会话的仪表，从下一步重新计。` };
    },
  });

  ctx.tools.register(
    defineTool({
      name: 'quota_meter',
      description: '查看当前会话的实时 token 用量、估算花费，以及按当前增速第几步撑满上下文、第几步烧完预算。用户问"花了多少/还剩多少预算/还能跑几步"或长任务开始前自查时用。',
      parameters: {},
      output: {
        schema: { type: 'string' } as const,
        render: (_args, value) => [{ type: 'text', text: value }],
      },
      presentCall: () => presentCallCard('读取实时用量'),
      presentResult: (_args, _result) => {
        const id = currentSessionId();
        const totals = (id !== undefined ? sessions.get(id) : undefined) ?? emptyTotals();
        return presentResultCard(totals, options(), id === undefined ? null : forecastFor(id));
      },
      async execute() {
        const id = currentSessionId();
        const totals = readProjectedState() ?? ((id !== undefined ? sessions.get(id) : undefined) ?? aggregateAll());
        const forecast = id === undefined ? null : forecastFor(id);
        return [renderMeter('会话实时用量', totals, options()), renderForecastLine(forecast), ...projectionLines(id)].join('\n');
      },
    }),
  );

  log.info(`mounted · ${store.path} · budget=${config.budgetTokens || 'off'} · inject=${config.inject}`);
}
"
    },
    {
      "path": "src/meter.ts",
      "content": "/** Pure meter model for dsh-plugin-quota: live per-session token/cost totals
 * folded from assistant/message usage events, rendered as a text gauge for the
 * system prompt, a full panel for /qm, and generic presentation cards.
 * Doubles as the family's reference template for universal plugin development
 * (events + command + tool + section + presentation hooks, all testable).
 * @module meter */

export interface UsageTotals {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  /** one per `assistant/message` event — dsh emits those per *step*, so the panel
   * says 步, not 轮 (a user turn runs many of them). */
  turns: number;
  /** micro-units of the configured currency; only accumulates for priced models */
  costMicros: number;
}

export function emptyTotals(): UsageTotals {
  return { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, turns: 0, costMicros: 0 };
}

export interface RawUsage {
  inputTokens?: number;
  outputTokens?: number;
  cacheReadTokens?: number;
  reasoningTokens?: number;
}

const nonNeg = (value: unknown): number => (typeof value === 'number' && Number.isFinite(value) && value > 0 ? Math.floor(value) : 0);

export function addUsage(totals: UsageTotals, usage: RawUsage): UsageTotals {
  return {
    inputTokens: totals.inputTokens + nonNeg(usage.inputTokens),
    outputTokens: totals.outputTokens + nonNeg(usage.outputTokens) + nonNeg(usage.reasoningTokens),
    cacheReadTokens: totals.cacheReadTokens + nonNeg(usage.cacheReadTokens),
    turns: totals.turns + 1,
    costMicros: totals.costMicros,
  };
}

/** One price row: matched by model id prefix (family style: simple + honest). */
export interface PriceRow {
  match: string;
  currency: string;
  perMillion: { input: number; output: number; cacheRead: number };
  /** the model's context window, needed for the fill-point projection. dsh exposes no
   * model catalogue to plugins, so this is the only source; absent = no projection. */
  contextWindow?: number;
}

export function priceFor(rows: PriceRow[], modelId: string): PriceRow | null {
  return rows.find((row) => modelId.toLowerCase().includes(row.match.toLowerCase())) ?? null;
}

/** Micro-currency estimate for one usage event; 0 when the model is unpriced. */
export function costMicrosOf(price: PriceRow | null, usage: RawUsage): number {
  if (!price) return 0;
  const m = 1_000_000;
  const input = nonNeg(usage.inputTokens) * price.perMillion.input;
  const output = (nonNeg(usage.outputTokens) + nonNeg(usage.reasoningTokens)) * price.perMillion.output;
  const cacheRead = nonNeg(usage.cacheReadTokens) * price.perMillion.cacheRead;
  return Math.round(((input + output + cacheRead) / m) * 1_000_000);
}

export function formatMoney(micros: number, currency: string): string {
  if (micros <= 0) return '0';
  const value = micros / 1_000_000;
  const digits = value < 0.01 ? 4 : value < 1 ? 3 : 2;
  return `${value.toFixed(digits)} ${currency}`;
}

export function compactTokens(n: number): string {
  if (n < 1000) return String(n);
  if (n < 1_000_000) return `${(n / 1000).toFixed(n < 10_000 ? 1 : 0)}k`;
  return `${(n / 1_000_000).toFixed(2)}M`;
}

/** ▰▰▰▱▱ bar of `width` cells at `ratio`, clamped to [0,1]. */
export function gauge(ratio: number, width = 10): string {
  const clamped = Math.max(0, Math.min(1, Number.isFinite(ratio) ? ratio : 0));
  const filled = Math.round(clamped * width);
  return '▰'.repeat(filled) + '▱'.repeat(width - filled);
}

export interface MeterOptions {
  budgetTokens?: number;
  prices?: PriceRow[];
  /** currency shown when no price row matched (token-only mode renders no money) */
  now?: Date;
}

/** Full panel for /qm and the quota_meter tool: per-session gauge + totals. */
export function renderMeter(title: string, totals: UsageTotals, options: MeterOptions = {}): string {
  const lines = [`${title}`];
  const cacheNote = totals.cacheReadTokens > 0 ? `（缓存命中 ${compactTokens(totals.cacheReadTokens)}）` : '';
  lines.push(`输入 ${compactTokens(totals.inputTokens)}${cacheNote} · 输出 ${compactTokens(totals.outputTokens)} · ${totals.turns} 步`);
  const price = options.prices?.[0];
  if (totals.costMicros > 0 && price) lines.push(`估算花费 ≈ ${formatMoney(totals.costMicros, price.currency)}`);
  if (options.budgetTokens && options.budgetTokens > 0) {
    const total = totals.inputTokens + totals.outputTokens;
    lines.push(`预算 ${gauge(total / options.budgetTokens)} ${compactTokens(total)}/${compactTokens(options.budgetTokens)}`);
  }
  return lines.join('\n');
}

/** Budget warning grades injected after the gauge: 80% is a heads-up, 100%
 * tells the model to wrap up — the section is the one channel guaranteed to
 * reach the model every turn, so the nudge rides there. */
export function budgetWarningGrade(total: number, budgetTokens: number | undefined): string {
  if (!budgetTokens || budgetTokens <= 0 || !Number.isFinite(budgetTokens)) return '';
  const ratio = total / budgetTokens;
  if (ratio >= 1) return ' · ⚠ 预算已烧穿，强烈建议开新会话';
  if (ratio >= 0.8) return ' · ⚠ 预算已过 80%，注意收尾';
  return '';
}

/** One-line live gauge injected into the system prompt every turn. */
export function renderCompactLine(totals: UsageTotals, options: MeterOptions = {}): string {
  const total = totals.inputTokens + totals.outputTokens;
  const budgetPart = options.budgetTokens && options.budgetTokens > 0 ? ` / ${compactTokens(options.budgetTokens)} ${gauge(total / options.budgetTokens, 8)}` : '';
  const price = options.prices?.[0];
  const money = totals.costMicros > 0 && price ? ` · ≈${formatMoney(totals.costMicros, price.currency)}` : '';
  const warning = budgetWarningGrade(total, options.budgetTokens);
  return `实时用量：${compactTokens(total)} tok${budgetPart} · ${totals.turns} 步${money}${warning}（/qm 详情）`;
}

/** Per-model leaderboard for /qm-top: rows sorted by input+output (the same
 * "used" figure the gauges show), capped at `limit`. Empty map renders a plain
 * "no data" line — a leaderboard over nothing must not look like a zero row. */
export function renderModelTop(title: string, byModel: Record<string, UsageTotals> | undefined, options: MeterOptions = {}, limit = 5): string {
  const entries = Object.entries(byModel ?? {}).filter(([, totals]) => totals.turns > 0);
  if (!entries.length) return `${title}：还没有分模型数据（跑一步后再看）`;
  entries.sort((a, b) => b[1].inputTokens + b[1].outputTokens - (a[1].inputTokens + a[1].outputTokens));
  const currency = options.prices?.[0]?.currency;
  const lines = [`${title} 按模型 Top ${Math.min(limit, entries.length)}（共 ${entries.length} 个模型）`];
  for (const [model, totals] of entries.slice(0, limit)) {
    const money = totals.costMicros > 0 && currency ? ` · ≈${formatMoney(totals.costMicros, currency)}` : '';
    lines.push(`- ${model}：${compactTokens(totals.inputTokens + totals.outputTokens)} tok · ${totals.turns} 步${money}`);
  }
  return lines.join('\n');
}

/** One `assistant/message` step. dsh emits these per *step*, not per user turn:
 * `input` is the uncached prefix delta, `cacheRead` the reused prefix. */
export interface StepUsage {
  input: number;
  output: number;
  cacheRead: number;
}

export function stepOf(usage: RawUsage): StepUsage {
  return {
    input: nonNeg(usage.inputTokens),
    output: nonNeg(usage.outputTokens) + nonNeg(usage.reasoningTokens),
    cacheRead: nonNeg(usage.cacheReadTokens),
  };
}

/** Tool results landing after the last step are the one part the meter cannot
 * see; 15% slack on the new content keeps the estimate from reading low. */
export const TOOL_SLACK = 0.15;

export interface TurnForecast {
  /** billable (uncached) input for the next step */
  inputEst: number;
  /** the already-cached prefix, expected to hit again */
  cacheReadEst: number;
  promptEst: number;
  outputP50: number;
  outputP85: number;
  costP50Micros: number;
  costP85Micros: number;
  /** currency the cost figures are in, from the row that actually matched the
   * session's model — never the first row of the price table */
  currency: string | null;
  basis: number;
}

/** Nearest-rank percentile over a copy; empty input is 0, one sample is itself. */
export function percentile(values: readonly number[], q: number): number {
  const sorted = values.filter((value) => Number.isFinite(value)).sort((a, b) => a - b);
  if (!sorted.length) return 0;
  const rank = Math.min(sorted.length, Math.max(1, Math.ceil(q * sorted.length)));
  return sorted[rank - 1]!;
}

const usableSteps = (history: readonly StepUsage[]): StepUsage[] =>
  history.filter((step) => step && Number.isFinite(step.input) && Number.isFinite(step.output) && Number.isFinite(step.cacheRead));

/** Next-step estimate from the step history: the prefix grows by what the model
 * just wrote, the cached part stays cached, output is the session's own spread.
 * Null with no history — a forecast invented before the first step is a lie. */
export function predictNextTurn(history: readonly StepUsage[], price: PriceRow | null): TurnForecast | null {
  const steps = usableSteps(history);
  if (!steps.length) return null;
  const last = steps[steps.length - 1]!;
  const inputEst = Math.round((last.input + last.output) * (1 + TOOL_SLACK));
  const cacheReadEst = last.cacheRead;
  const outputs = steps.map((step) => step.output);
  const outputP50 = percentile(outputs, 0.5);
  const outputP85 = percentile(outputs, 0.85);
  const at = (output: number): number => costMicrosOf(price, { inputTokens: inputEst, outputTokens: output, cacheReadTokens: cacheReadEst });
  return {
    inputEst,
    cacheReadEst,
    promptEst: inputEst + cacheReadEst,
    outputP50,
    outputP85,
    costP50Micros: at(outputP50),
    costP85Micros: at(outputP85),
    currency: price?.currency ?? null,
    basis: steps.length,
  };
}

/** The panel line: what the next step is going to cost before it happens. */
export function renderForecastLine(forecast: TurnForecast | null): string {
  if (!forecast) return '下步预估：还没有已完成的步（跑完一步再来看）';
  const low = forecast.currency ? formatMoney(forecast.costP50Micros, forecast.currency) : '';
  const high = forecast.currency ? formatMoney(forecast.costP85Micros, forecast.currency) : '';
  // the spread is printed only when it survives rounding — "0.02–0.02 USD" is noise
  const money = forecast.currency && forecast.costP85Micros > 0 ? ` · ≈${low === high ? low : `${low}–${high}`}` : '';
  const cachePart = forecast.cacheReadEst > 0 ? ` + 缓存复用 ${compactTokens(forecast.cacheReadEst)}` : '';
  const outputs = forecast.outputP85 > forecast.outputP50 ? `${compactTokens(forecast.outputP50)}–${compactTokens(forecast.outputP85)}` : compactTokens(forecast.outputP50);
  return `下步预估：新输入 ~${compactTokens(forecast.inputEst)}${cachePart}（提示词 ~${compactTokens(forecast.promptEst)}） · 输出 ${outputs}（P50–P85，${forecast.basis} 步为据）${money}`;
}

/** What the model saw at one step: the uncached delta, the reused prefix, and what
 * it wrote back — which is the bulk of the *next* step's prompt. */
const promptOf = (step: StepUsage): number => step.input + step.cacheRead + step.output;

/** Median step-to-step prompt growth: a single huge tool result must not fake the
 * slope, so the middle delta wins and the mean never does. 0 below two steps. */
export function promptGrowth(history: readonly StepUsage[]): number {
  const steps = usableSteps(history);
  if (steps.length < 2) return 0;
  return percentile(steps.slice(1).map((step, index) => promptOf(step) - promptOf(steps[index]!)), 0.5);
}

export interface WindowProjection {
  /** prompt tokens in front of the model at the last observed step */
  promptNow: number;
  growthPerStep: number;
  /** more steps before promptNow reaches contextWindow; null = no honest fill point */
  stepsToFull: number | null;
  /** session step index where it fills; null with no fill point */
  fullAtStep: number | null;
  /** false for a flat or shrinking session — those never fill up */
  willGrow: boolean;
  /** steps behind the reading; under 2 the slope is not observable yet */
  basis: number;
}

/** When does this session's context window fill up? `observedSteps` is the session's
 * true step count when the retained history is shorter than the session (history is
 * capped per session), so the printed index is not off by the trim. */
export function projectWindow(history: readonly StepUsage[], contextWindow: number, observedSteps?: number): WindowProjection {
  const steps = usableSteps(history);
  const promptNow = steps.length ? promptOf(steps[steps.length - 1]!) : 0;
  const growthPerStep = promptGrowth(steps);
  const willGrow = growthPerStep > 0;
  const usable = Number.isFinite(contextWindow) && contextWindow > 0;
  let stepsToFull: number | null = null;
  if (usable && promptNow >= contextWindow) stepsToFull = 0;
  else if (usable && willGrow) stepsToFull = Math.ceil((contextWindow - promptNow) / growthPerStep);
  const at = Math.max(steps.length, observedSteps ?? 0);
  return { promptNow, growthPerStep, stepsToFull, fullAtStep: stepsToFull === null ? null : at + stepsToFull, willGrow, basis: steps.length };
}

export interface BudgetProjection {
  totalUsed: number;
  budgetTokens: number;
  /** steps until cumulative usage crosses the budget; null = no budget or no growth,
   * 0 = already crossed */
  stepsLeft: number | null;
  /** used/budget; null when there is no budget, so no ratio exists to report */
  ratio: number | null;
}

/** How many steps of this session's own growth still fit in `budgetTokens`. */
export function projectBudget(totalUsed: number, budgetTokens: number, growthPerStep: number): BudgetProjection {
  if (!Number.isFinite(budgetTokens) || budgetTokens <= 0) return { totalUsed, budgetTokens, stepsLeft: null, ratio: null };
  const remaining = budgetTokens - totalUsed;
  const stepsLeft = remaining <= 0 ? 0 : growthPerStep > 0 ? Math.ceil(remaining / growthPerStep) : null;
  return { totalUsed, budgetTokens, stepsLeft, ratio: totalUsed / budgetTokens };
}

/** Panel line: the step at which this session runs out of context. */
export function renderWindowLine(projection: WindowProjection | null, contextWindow: number | null): string {
  const head = '撑满预测：';
  if (!contextWindow || !Number.isFinite(contextWindow) || contextWindow <= 0) return `${head}未配置该模型的 contextWindow，算不出撑满点`;
  if (!projection || projection.basis === 0) return `${head}还没有已完成的步（跑完一步再来看）`;
  const limit = compactTokens(contextWindow);
  const now = `~${compactTokens(projection.promptNow)}/${limit}`;
  if (projection.stepsToFull === 0) return `${head}~${compactTokens(projection.promptNow)} 已顶到 ${limit} 上限 · 立刻 /compact 或换会话`;
  if (projection.stepsToFull === null) {
    return projection.basis < 2
      ? `${head}${now} · 只有 1 步，还看不出增速`
      : `${head}${now} · 看不到撑满的迹象（增速 ≤ 0）`;
  }
  return `${head}按当前增速，第 ${projection.fullAtStep} 步（再 ${projection.stepsToFull} 步）撑满 ${limit} 上下文 · 建议在那之前 /compact 或换会话`;
}

/** Panel line: the step at which this session runs out of budget. */
export function renderBudgetLine(budget: BudgetProjection): string {
  const head = '预算预测：';
  if (budget.ratio === null) return `${head}未配置 budgetTokens，没有预算可烧`;
  const used = `已用 ${Math.round(budget.ratio * 100)}%`;
  if (budget.stepsLeft === 0) return `${head}⚠ 已烧穿 ${compactTokens(budget.budgetTokens)} 预算（${used}）· 该收尾了`;
  if (budget.stepsLeft === null) return `${head}~${compactTokens(budget.totalUsed)}/${compactTokens(budget.budgetTokens)} · 看不到烧穿的迹象（增速 ≤ 0）`;
  return `${head}按当前增速，再 ${budget.stepsLeft} 步烧到 ${compactTokens(budget.budgetTokens)}（${used}）`;
}

/** The published budget contract. Other plugins read `summary.json` instead of
 * digging through session-keyed `totals.json`, so a per-session uuid layout stays
 * an internal detail of quota. */
export interface QuotaSummary {
  updatedAt: string;
  currency: string;
  budgetTokens: number;
  /** the hottest single session right now */
  maxSessionTokens: number;
  /** null when no budget is set — "how hot" has no meaning without one */
  maxSessionRatio: number | null;
  /** next-step prompt estimate for the session that is currently running */
  nextTurnEstTokens: number | null;
  /** running session's model context window, null when unconfigured. These three are
   * append-only to `summary.json` — task-forge and ide-hub read it, so nothing existing
   * here may be renamed or redefined, only added. */
  contextWindow: number | null;
  /** steps until the running session fills that window, null = no fill point */
  stepsUntilFull: number | null;
  /** steps until the running session crosses budgetTokens, null = no budget */
  stepsUntilBudget: number | null;
  todayTokens: number;
  todayCostMicros: number;
  sessions: number;
}

export function summarise(input: {
  sessions: readonly UsageTotals[];
  today: UsageTotals;
  budgetTokens: number;
  forecast: TurnForecast | null;
  currency?: string | undefined;
  now?: Date;
  contextWindow?: number | null;
  stepsUntilFull?: number | null;
  stepsUntilBudget?: number | null;
}): QuotaSummary {
  const used = input.sessions.map((totals) => totals.inputTokens + totals.outputTokens);
  const maxSessionTokens = used.length ? Math.max(...used) : 0;
  const budgetTokens = Math.max(0, Math.round(input.budgetTokens));
  return {
    updatedAt: (input.now ?? new Date()).toISOString(),
    currency: input.currency ?? 'CNY',
    budgetTokens,
    maxSessionTokens,
    maxSessionRatio: budgetTokens > 0 ? maxSessionTokens / budgetTokens : null,
    nextTurnEstTokens: input.forecast ? input.forecast.promptEst : null,
    contextWindow: input.contextWindow ?? null,
    stepsUntilFull: input.stepsUntilFull ?? null,
    stepsUntilBudget: input.stepsUntilBudget ?? null,
    todayTokens: input.today.inputTokens + input.today.outputTokens,
    todayCostMicros: input.today.costMicros,
    sessions: input.sessions.length,
  };
}

/** These mirror GenericCallView/GenericResultView from @deepseek-ai/dsh-tools with the
 * fields this plugin always fills in made required — a UI bridge still accepts them
 * structurally, and callers stop having to unwrap `title?: string` everywhere. */
export interface CallCard {
  card: 'generic';
  title: string;
  /** the ToolCallKind for a pending call; a result view has no kind */
  kind: 'other';
  rawInput: string;
}

export interface ResultCard {
  card: 'generic';
  title: string;
  content: Array<{ type: 'text'; text: string }>;
}

/** Generic presentation card for the calling state (while the tool runs). */
export function presentCallCard(title: string): CallCard {
  return { card: 'generic', title, kind: 'other', rawInput: title };
}

/** Generic presentation card for the result state. A result view has no `kind`
 * or `rawInput` — those belong to the pending call; the body goes in `content`. */
export function presentResultCard(totals: UsageTotals, options: MeterOptions = {}, forecast?: TurnForecast | null): ResultCard {
  const price = options.prices?.[0];
  const money = totals.costMicros > 0 && price ? ` · ≈${formatMoney(totals.costMicros, price.currency)}` : '';
  const next = forecast ? ` · 下步 ~${compactTokens(forecast.promptEst)}` : '';
  return {
    card: 'generic',
    title: `${compactTokens(totals.inputTokens + totals.outputTokens)} tok · ${totals.turns} 步${money}${next}`,
    content: [{ type: 'text', text: renderMeter('会话实时用量', totals, options) + (forecast ? `\n${renderForecastLine(forecast)}` : '') }],
  };
}

/** One billing-log row, as new-api writes it: flat micro-quota for the whole
 * call, no cache split. */
export interface BillingRow {
  model: string;
  quota: number;
  tokens: number;
}

/** Derive real prices from the relay's own billing logs: $/M per model = quota
 * / 500000 (new-api's $1) / tokens * 1e6, averaged over each model's calls.
 * These are the numbers the user is ACTUALLY billed, not brochure prices. */
export function calibratePrices(rows: BillingRow[]): PriceRow[] {
  const buckets = new Map<string, { billed: number; tokens: number; calls: number }>();
  for (const row of rows) {
    if (!row.model || !Number.isFinite(row.quota) || row.quota <= 0 || !Number.isFinite(row.tokens) || row.tokens <= 0) continue;
    const bucket = buckets.get(row.model) ?? { billed: 0, tokens: 0, calls: 0 };
    bucket.billed += row.quota;
    bucket.tokens += row.tokens;
    bucket.calls += 1;
    buckets.set(row.model, bucket);
  }
  const prices: PriceRow[] = [];
  for (const [model, bucket] of buckets) {
    if (bucket.tokens < 1000) continue; // not enough data to be meaningful
    const usdPerMillion = (bucket.billed / bucket.tokens) * 1e6 / 500_000;
    if (!Number.isFinite(usdPerMillion) || usdPerMillion <= 0) continue;
    const rounded = Math.round(usdPerMillion * 100) / 100;
    prices.push({ match: model, currency: 'USD', perMillion: { input: rounded, output: rounded, cacheRead: rounded } });
  }
  return prices.sort((a, b) => a.match.localeCompare(b.match));
}
